// Normalise the enquiry. Input: POST body { question, name?, email? }
const body = $json.body || $json;
const rawQuestion = String(body.question || body.message || '').trim();
const name = String(body.name || '').trim().slice(0, 80);
const email = String(body.email || '').trim().slice(0, 120);

// Redact anything that looks like a card number or a pasted password/code
// before the text goes into a handoff note.
let safe = rawQuestion;
let sensitive = false;
safe = safe.replace(/\b\d(?:[ -]?\d){12,18}\b/g, () => { sensitive = true; return '[removed card-like number]'; });
safe = safe.replace(/\b(password|passcode|pin|otp|one[- ]time code)\b\s*(?:is|:|=)?\s*\S+/gi, (m, w) => { sensitive = true; return w + ' [removed]'; });

const text = ' ' + safe.toLowerCase()
  .replace(/[\u2018\u2019]/g, "'")
  .replace(/[^a-z0-9:$'\- ]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim() + ' ';

return {
  json: {
    receivedAt: new Date().toISOString(),
    question: safe.slice(0, 1000),
    text,
    name,
    email,
    hasReplyAddress: /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email),
    sensitive,
  },
};

// Small inline knowledge source for the fictional Northline Supplies.
// Edit, add or remove entries here. Keep each answer to facts you have approved.
// "keywords": a phrase scores 2 points, a single word scores 1 point.
const faq = [
  {
    id: 'hours',
    topic: 'Desk hours',
    keywords: ['opening hours', 'business hours', 'desk hours', 'what time', 'open', 'hours', 'closed', 'close'],
    answer: 'The Northline Supplies support desk is open Monday to Friday, 8:00 am to 5:00 pm AEST. Messages sent after hours are picked up the next business morning.',
  },
  {
    id: 'delivery-times',
    topic: 'Delivery times',
    keywords: ['how long', 'delivery time', 'delivery times', 'shipping time', 'how many days', 'business days', 'arrive', 'delivery', 'shipping'],
    answer: 'Standard road delivery takes 2 to 4 business days to Sydney metro, 3 to 5 to other metro areas, 4 to 7 to regional areas and 7 to 12 to remote areas.',
  },
  {
    id: 'cut-off',
    topic: 'Order cut-off',
    keywords: ['cut-off', 'cut off', 'cutoff', 'same day', 'same-day', 'ship today', 'dispatch today', 'order by', 'dispatched today'],
    answer: 'Orders paid by 1:00 pm AEST ship the same business day when the items are in stock. Orders paid after that ship the next business day.',
  },
  {
    id: 'free-shipping',
    topic: 'Free shipping',
    keywords: ['free shipping', 'free freight', 'free delivery', 'shipping cost', 'freight cost', 'delivery cost', 'how much is shipping', 'how much is delivery', 'freight', 'free'],
    answer: 'Standard shipping is free on paid orders of A$150 or more excluding GST. Below that, shipping is quoted at checkout.',
  },
  {
    id: 'returns',
    topic: 'Returns window',
    keywords: ['return policy', 'return window', 'send back', 'give back', 'return', 'returns', 'exchange', 'unopened'],
    answer: 'Unused, unopened stock can be returned within 14 days of delivery. The buyer pays return freight unless we sent the wrong item. Opened, used or cut-to-length items, and PPE that has touched skin, cannot be returned.',
  },
  {
    id: 'range',
    topic: 'What we sell',
    keywords: ['what do you sell', 'do you sell', 'do you stock', 'product range', 'products', 'range', 'sell', 'stock', 'fasteners', 'packaging', 'ppe'],
    answer: 'Northline Supplies sells workshop consumables, fasteners, packaging and PPE to trade and small retail accounts.',
  },
];

return {
  json: {
    ...$json,
    faq,
    // A match needs at least this many points and must beat the runner-up.
    minScore: 2,
    // Words that always go to a person, even if a FAQ entry also matches.
    humanRequestPhrases: ['speak to a person', 'speak to someone', 'speak with a person', 'talk to a person', 'talk to someone', 'talk to a human', 'real person', 'human', 'call me', 'phone me', 'ring me', 'agent', 'someone call', 'representative', 'manager'],
    handoffTopicPhrases: ['refund', 'chargeback', 'cancel', 'credit', 'damaged', 'crushed', 'broken', 'missing', 'wrong item', 'wrong sku', 'short shipped', 'where is my order', 'order status', 'track', 'tracking', 'change my address', 'change the address', 'new address', 'quote', 'discount', 'trade account', 'invoice', 'complaint', 'lawyer', 'legal', 'insurance', 'safe for', 'injury', 'allergic', 'on hold'],
  },
};

// Decide: answer from the knowledge source, or hand off to a person.
const d = $json;
// text is lower-case with single spaces and a space at each end.
const hasWord = (p) => d.text.includes(' ' + p + ' ');   // whole word or phrase
const hasStart = (p) => d.text.includes(' ' + p);        // word start: cancel matches cancelled

let reason = null;
let match = null;
let score = 0;
let runnerUp = 0;

if (!d.question) {
  reason = 'empty_question';
} else if (d.sensitive) {
  reason = 'sensitive_details_shared';
} else if (d.humanRequestPhrases.some((p) => hasStart(p))) {
  reason = 'customer_asked_for_a_person';
} else if (/\bnl-\d{5}\b/i.test(d.question) || d.handoffTopicPhrases.some((p) => hasStart(p))) {
  reason = 'needs_a_person_to_action';
} else {
  const scored = d.faq.map((e) => {
    let s = 0;
    for (const k of e.keywords) {
      if (hasWord(k)) s += k.includes(' ') ? 2 : 1;
    }
    return { e, s };
  }).sort((a, b) => b.s - a.s);
  score = scored[0].s;
  runnerUp = scored[1].s;
  if (score >= d.minScore && score > runnerUp) {
    match = scored[0].e;
  } else {
    reason = score === 0 ? 'no_match_in_knowledge_source' : 'not_confident_enough';
  }
}

const { faq, humanRequestPhrases, handoffTopicPhrases, minScore, ...rest } = d;
return {
  json: {
    ...rest,
    confident: Boolean(match),
    matchedId: match ? match.id : null,
    matchedTopic: match ? match.topic : null,
    answer: match ? match.answer : null,
    score,
    runnerUp,
    handoffReason: reason,
  },
};

// Write the note the human sees. Customer text has card-like numbers and
// pasted passwords removed already (see the Normalise node).
const d = $json;
const ref = 'ENQ-' + Date.now().toString(36).toUpperCase();
const lines = [
  'FAQ desk handoff (' + ref + ')',
  '',
  'Why: ' + d.handoffReason,
  'Received: ' + d.receivedAt,
  'Customer name: ' + (d.name || '(not given)'),
  'Reply address: ' + (d.hasReplyAddress ? d.email : '(not given)'),
  '',
  'Customer question, verbatim:',
  d.question || '(empty)',
  '',
  'Note: no answer was given beyond "a person will reply". Nothing was promised (no refund, replacement or date).',
];
return {
  json: {
    ...d,
    reference: ref,
    handoffSubject: '[FAQ desk] ' + ref + ' - ' + d.handoffReason.replace(/_/g, ' '),
    handoffText: lines.join('\n'),
  },
};
